; main.s -- PHYSICS main program ($0800-$1CFF, tracks 8-9)
; Regenerated by tools/gen.py from the original disk; see README.md.
; Included by physics.s (segment MAIN).

;---------------------------------------------------------------------------
; PHYSICS -- main program, loaded at $0800-$1CFF from tracks 8-9.
;
; Up to three spinning balls fall under gravity, bounce off each other,
; off the screen walls and off seven boxes that dent and wobble when hit.
; Animation is double-buffered on HGR pages 1/2, timed by the //e vertical
; blank flag RDVBLBAR ($C019).
;---------------------------------------------------------------------------
start:
        jmp  init

;---------------------------------------------------------------------------
; main_loop -- once per displayed frame:
;   read_keyboard; unless paused run `steps` physics steps (one per
;   vertical blank since the last flip, 2-4), so the simulation runs at
;   the display's field rate even though frames take 2+ fields to draw;
;   render_frame into the hidden page; wait_and_flip.
;---------------------------------------------------------------------------
main_loop:
        jsr  read_keyboard
        lda  paused                     ; paused?
        bne  render
        lda  steps
        sta  stepcnt
L080E:
        jsr  physics_step
        dec  stepcnt
        bne  L080E
render:
        jsr  render_frame
        jsr  wait_and_flip
        inc  frames
        bne  L0821
        inc  frames+1
L0821:
        jmp  main_loop

;---------------------------------------------------------------------------
; physics_step -- one simulation tick for every ball:
;   1. integrate_ball for every awake ball (gravity, clamp, move, rotate);
;   2. collide_all_pairs (ball/ball);
;   3. per ball: collide_boxes (awake) or re-assert its resting contact
;      (asleep), check_ball_life, write back;
;   4. box_spring for boxes 4-10 (dents relax as damped springs);
;   5. while fewer than 3 balls exist, spawn one every 90 steps.
;---------------------------------------------------------------------------
physics_step:
        ldx  #$00
L0826:
        lda  ob_asleep,x
        bne  L0832
        stx  curball
        jsr  integrate_ball
        ldx  curball
L0832:
        inx
        cpx  nballs
        bcc  L0826
        jsr  collide_all_pairs
        ldx  #$0A
        lda  #$00
L083E:
        sta  bx_hit,x
        dex
        cpx  #$04
        bcs  L083E
        ldx  #$00
step_ball_loop:
        stx  curball
        lda  RDVBLBAR                   ; VBL edge counting (see wait_vbl)
        and  #$80
        cmp  vblprev
        beq  L085B
        sta  vblprev
        and  #$80
        bne  L085B
        inc  vblcount
L085B:
        ldx  curball
        jsr  load_ball
        ldx  curball
        lda  ob_asleep,x                ; asleep?
        beq  L0886
        ldy  ob_hitbox,x                ; resting on a box: keep the box pressed
        beq  L088E
        lda  #$01
        sta  bx_hit,y
        lda  ob_hitside,x
        sta  bx_hitside,y
        lda  ob_hitpos,x
        sta  bx_hitpos,y
        lda  ob_hitdepth,x
        sta  bx_hitdepth,y
        jmp  L088E
L0886:
        lda  #$00
        sta  ob_hitbox,x
        jsr  collide_boxes
L088E:
        jsr  check_ball_life
        ldx  curball
        jsr  save_ball
        ldx  curball
        inx
        cpx  nballs
        bcc  step_ball_loop
        ldx  #$04
L089F:
        stx  boxloop
        jsr  box_spring
        ldx  boxloop
        inx
        cpx  #$0B
        bcc  L089F
        lda  nballs
        cmp  #$03
        bcs  L08C4
        inc  spawntmr
        lda  spawntmr
        cmp  #$5A                       ; 90 steps
        bcc  L08C4
        lda  #$00
        sta  spawntmr
        ldx  nballs
        jsr  spawn_ball
        inc  nballs
L08C4:
        rts

;---------------------------------------------------------------------------
; collide_all_pairs -- collide_pair for every pair (a < b) of balls in play.
;---------------------------------------------------------------------------
collide_all_pairs:
        ldx  #$00
L08C7:
        txa
        tay
L08C9:
        iny
        cpy  nballs
        bcs  L08DC
        stx  ball_a
        sty  ball_b
        jsr  collide_pair
        ldx  ball_a
        ldy  ball_b
        jmp  L08C9
L08DC:
        inx
        cpx  nballs
        bcc  L08C7
        rts

;---------------------------------------------------------------------------
; check_ball_life -- age the ball; count steps where |vx| and |vy| are
; both under 1/8 px/step.  30 still steps -> put it to sleep (no more
; integration); 90 still steps or an age of 1500 steps -> respawn it.
;---------------------------------------------------------------------------
check_ball_life:
        inc  bage
        bne  L08E8
        inc  bage+1
L08E8:
        ldx  #$14
        jsr  is_slow
        bcs  L0903
        ldx  #$16
        jsr  is_slow
        bcs  L0903
        inc  bstill
        lda  bstill
        cmp  #$5A                       ; 90 still steps
        bcc  L0907
        ldx  curball
        jmp  spawn_ball
L0903:
        lda  #$00
        sta  bstill
L0907:
        lda  bage                       ; age >= 1500?
        cmp  #$DC
        lda  bage+1
        sbc  #$05
        bcc  L0916
        ldx  curball
        jmp  spawn_ball
L0916:
        lda  bstill
        cmp  #$1E                       ; 30 still steps -> sleep
        bcc  L0923
        ldx  curball
        lda  #$01
        sta  ob_asleep,x
L0923:
        rts

;---------------------------------------------------------------------------
; is_slow -- C=0 when the 16-bit signed value at $00,X lies within
; +-$20 (+-1/8 px/step).
;---------------------------------------------------------------------------
is_slow:
        lda  $00,x
        clc
        adc  #$20
        tay
        lda  $01,x
        adc  #$00
        bne  L0933
        cpy  #$40
        rts
L0933:
        sec
        rts

;---------------------------------------------------------------------------
; load_ball_all -- copy ball X's state (incl. rotation angle) from the
; object arrays at $0200 into zero page.
;---------------------------------------------------------------------------
load_ball_all:
        lda  ob_xlo,x
        sta  bx
        lda  ob_xhi,x
        sta  bx+1
        lda  ob_ylo,x
        sta  by
        lda  ob_yhi,x
        sta  by+1
        lda  ob_vxlo,x
        sta  bvx
        lda  ob_vxhi,x
        sta  bvx+1
        lda  ob_vylo,x
        sta  bvy
        lda  ob_vyhi,x
        sta  bvy+1
        lda  ob_spinlo,x
        sta  bspin
        lda  ob_spinhi,x
        sta  bspin+1
        lda  ob_ratelo,x
        sta  barate
        lda  ob_ratehi,x
        sta  barate+1
        lda  ob_agelo,x
        sta  bage
        lda  ob_agehi,x
        sta  bage+1
        lda  ob_anglo,x
        sta  bangle
        lda  ob_anghi,x
        sta  bangle+1
        lda  ob_still,x
        sta  bstill
        rts

;---------------------------------------------------------------------------
; save_ball_all -- inverse of load_ball_all.
;---------------------------------------------------------------------------
save_ball_all:
        lda  bx
        sta  ob_xlo,x
        lda  bx+1
        sta  ob_xhi,x
        lda  by
        sta  ob_ylo,x
        lda  by+1
        sta  ob_yhi,x
        lda  bvx
        sta  ob_vxlo,x
        lda  bvx+1
        sta  ob_vxhi,x
        lda  bvy
        sta  ob_vylo,x
        lda  bvy+1
        sta  ob_vyhi,x
        lda  bspin
        sta  ob_spinlo,x
        lda  bspin+1
        sta  ob_spinhi,x
        lda  barate
        sta  ob_ratelo,x
        lda  barate+1
        sta  ob_ratehi,x
        lda  bage
        sta  ob_agelo,x
        lda  bage+1
        sta  ob_agehi,x
        lda  bangle
        sta  ob_anglo,x
        lda  bangle+1
        sta  ob_anghi,x
        lda  bstill
        sta  ob_still,x
        rts

;---------------------------------------------------------------------------
; load_ball -- as load_ball_all but without the rotation angle.
;---------------------------------------------------------------------------
load_ball:
        lda  ob_xlo,x
        sta  bx
        lda  ob_xhi,x
        sta  bx+1
        lda  ob_ylo,x
        sta  by
        lda  ob_yhi,x
        sta  by+1
        lda  ob_vxlo,x
        sta  bvx
        lda  ob_vxhi,x
        sta  bvx+1
        lda  ob_vylo,x
        sta  bvy
        lda  ob_vyhi,x
        sta  bvy+1
        lda  ob_spinlo,x
        sta  bspin
        lda  ob_spinhi,x
        sta  bspin+1
        lda  ob_ratelo,x
        sta  barate
        lda  ob_ratehi,x
        sta  barate+1
        lda  ob_agelo,x
        sta  bage
        lda  ob_agehi,x
        sta  bage+1
        lda  ob_still,x
        sta  bstill
        rts

;---------------------------------------------------------------------------
; save_ball -- inverse of load_ball.
;---------------------------------------------------------------------------
save_ball:
        lda  bx
        sta  ob_xlo,x
        lda  bx+1
        sta  ob_xhi,x
        lda  by
        sta  ob_ylo,x
        lda  by+1
        sta  ob_yhi,x
        lda  bvx
        sta  ob_vxlo,x
        lda  bvx+1
        sta  ob_vxhi,x
        lda  bvy
        sta  ob_vylo,x
        lda  bvy+1
        sta  ob_vyhi,x
        lda  bspin
        sta  ob_spinlo,x
        lda  bspin+1
        sta  ob_spinhi,x
        lda  barate
        sta  ob_ratelo,x
        lda  barate+1
        sta  ob_ratehi,x
        lda  bage
        sta  ob_agelo,x
        lda  bage+1
        sta  ob_agehi,x
        lda  bstill
        sta  ob_still,x
        rts

;---------------------------------------------------------------------------
; spawn_ball -- (re)create ball X at a random x (16-239), y = 10, with a
; small random horizontal speed (+-1/8 px) and a random spin.
;---------------------------------------------------------------------------
spawn_ball:
        stx  spawnidx
        jsr  random
        ldx  #$E0                       ; x = 16 + rnd*224/256
        jsr  mul8x8
        lda  prod+1
        clc
        adc  #$10
        sta  bx+1
        jsr  random
        sta  bx
        lda  #$00
        sta  by
        sta  bvy
        sta  bvy+1
        sta  bangle
        sta  bangle+1
        sta  bstill
        sta  bage
        sta  bage+1
        lda  #$0A                       ; y = 10
        sta  by+1
        jsr  random                     ; vx = (rnd & 63) - 32
        and  #$3F
        sec
        sbc  #$20
        sta  bvx
        lda  #$00
        sbc  #$00
        sta  bvx+1
        jsr  random
        sta  marg
        ldx  #$00
        tay
        bpl  L0AC0
        dex
L0AC0:
        stx  marg+1
        lda  #$03                       ; spin = rnd (signed) * 3
        jsr  mul_int
        lda  mres
        sta  bspin
        lda  mres+1
        sta  bspin+1
        jsr  spin_to_rate
        ldx  spawnidx
        lda  #$00
        sta  ob_asleep,x
        sta  ob_hitbox,x
        jmp  save_ball_all

;---------------------------------------------------------------------------
; key_spawn -- SPACE: add a ball if fewer than 3, else respawn the
; oldest one.
;---------------------------------------------------------------------------
key_spawn:
        lda  nballs
        cmp  #$03
        bcs  L0AF1
        ldx  nballs
        jsr  spawn_ball
        inc  nballs
        lda  #$00
        sta  spawntmr
        rts
L0AF1:
        lda  #$00
        sta  spawnidx
        ldx  #$01
L0AF7:
        ldy  spawnidx
        lda  ob_agelo,y
        cmp  ob_agelo,x
        lda  ob_agehi,y
        sbc  ob_agehi,x
        bcs  L0B09
        stx  spawnidx
L0B09:
        inx
        cpx  #$03
        bcc  L0AF7
        ldx  spawnidx
        jmp  spawn_ball

;---------------------------------------------------------------------------
; random -- 16-bit Galois LFSR (taps $B400), returns the low byte in A.
; Seeded with $AD3C at init, so every run plays the same sequence.
;---------------------------------------------------------------------------
random:
        lsr  seed+1
        ror  seed
        bcc  L0B1F
        lda  seed+1
        eor  #$B4                       ; LFSR taps
        sta  seed+1
L0B1F:
        lda  seed
        rts

;---------------------------------------------------------------------------
; render_frame -- draw the hidden page:
;   * update_boxes ($9400) redraws changed dents/sliders into the clean
;     background copy at $A000 and queues dirty rectangles;
;   * work out each ball's sprite position; a ball whose sprite is
;     identical to what this page already shows, and that no dirty rect
;     touches, is left alone (nw_keep) -- a moved ball overlapping it
;     forces it to be redrawn too;
;   * restore_dirty copies the dirty rects from $A000 to the page;
;   * erase_ball (copy back from $A000) then draw_ball for the others.
; The VBL counter is polled throughout because nothing else watches it.
;---------------------------------------------------------------------------
render_frame:
        lda  RDVBLBAR
        and  #$80
        cmp  vblprev
        beq  L0B33
        sta  vblprev
        and  #$80
        bne  L0B33
        inc  vblcount
L0B33:
        jsr  update_boxes
        lda  RDVBLBAR
        and  #$80
        cmp  vblprev
        beq  L0B47
        sta  vblprev
        and  #$80
        bne  L0B47
        inc  vblcount
L0B47:
        lda  drawpg                     ; pick this page's slot and row table
        beq  L0B4D
        lda  #$03
L0B4D:
        sta  pgslot
        lda  #<row_hi1
        ldx  #>row_hi1
        ldy  drawpg
        beq  L0B5B
        lda  #<row_hi2
        ldx  #>row_hi2
L0B5B:
        sta  rowhi_tab
        stx  rowhi_tab+1
        ldx  #$00
L0B61:
        stx  curball
        lda  RDVBLBAR
        and  #$80
        cmp  vblprev
        beq  L0B74
        sta  vblprev
        and  #$80
        bne  L0B74
        inc  vblcount
L0B74:
        ldx  curball
        lda  #$00
        sta  nw_keep,x
        cpx  nballs
        bcs  L0BB5
        jsr  load_ball_all
        jsr  sprite_pos
        ldx  curball
        lda  curball
        clc
        adc  pgslot
        tay
        lda  dr_valid,y
        beq  L0BB5
        lda  dr_col,y
        cmp  nw_col,x
        bne  L0BB5
        lda  dr_row,y
        cmp  nw_row,x
        bne  L0BB5
        lda  dr_frame,y
        cmp  nw_frame,x
        bne  L0BB5
        lda  dr_shift,y
        cmp  nw_shift,x
        bne  L0BB5
        jsr  check_unchanged
L0BB5:
        ldx  curball
        inx
        cpx  #$03
        bcc  L0B61
L0BBC:
        lda  #$00
        sta  tmp
        ldx  #$00
L0BC2:
        lda  nw_keep,x
        beq  L0BF4
        jsr  ball_rect
        ldy  #$00
L0BCC:
        sty  ball_b
        cpx  ball_b
        beq  L0BEF
        lda  nw_keep,y
        bne  L0BEF
        tya
        clc
        adc  pgslot
        tay
        lda  dr_valid,y
        beq  L0BED
        jsr  rect_overlap
        bcc  L0BED
        lda  #$00
        sta  nw_keep,x
        inc  tmp
L0BED:
        ldy  ball_b
L0BEF:
        iny
        cpy  #$03
        bcc  L0BCC
L0BF4:
        inx
        cpx  #$03
        bcc  L0BC2
        lda  tmp
        bne  L0BBC
        ldx  drawpg
        jsr  restore_dirty
        ldx  #$00
L0C04:
        stx  curball
        lda  RDVBLBAR
        and  #$80
        cmp  vblprev
        beq  L0C17
        sta  vblprev
        and  #$80
        bne  L0C17
        inc  vblcount
L0C17:
        ldx  curball
        lda  nw_keep,x
        bne  L0C26
        txa
        clc
        adc  pgslot
        tay
        jsr  erase_ball
L0C26:
        ldx  curball
        inx
        cpx  #$03
        bcc  L0C04
        ldx  #$00
L0C2F:
        stx  curball
        lda  RDVBLBAR
        and  #$80
        cmp  vblprev
        beq  L0C42
        sta  vblprev
        and  #$80
        bne  L0C42
        inc  vblcount
L0C42:
        ldx  curball
        lda  nw_keep,x
        bne  L0C4C
        jsr  draw_ball
L0C4C:
        ldx  curball
        inx
        cpx  nballs
        bcc  L0C2F
        rts

;---------------------------------------------------------------------------
; ball_rect -- $B0-$B3 = row span (12 rows) and byte span (3 bytes) of nw_* ball X.
;---------------------------------------------------------------------------
ball_rect:
        lda  nw_row,x
        sta  rect
        clc
        adc  #$0B
        sta  rect+1
        lda  nw_col,x
        sta  rect+2
        clc
        adc  #$02
        sta  rect+3
        rts

;---------------------------------------------------------------------------
; rect_overlap -- C=1 if the drawn sprite in slot Y overlaps the rect in $B0-$B3.
;---------------------------------------------------------------------------
rect_overlap:
        lda  dr_row,y
        cmp  rect+1
        beq  L0C72
        bcs  L0C88
L0C72:
        clc
        adc  #$0B
        cmp  rect
        bcc  L0C88
        lda  dr_col,y
        cmp  rect+3
        beq  L0C82
        bcs  L0C88
L0C82:
        clc
        adc  #$02
        cmp  rect+2
        rts
L0C88:
        clc
        rts

;---------------------------------------------------------------------------
; check_unchanged -- ball X's sprite is unchanged on this page; mark it
; nw_keep unless one of this page's pending dirty rects overlaps it.
;---------------------------------------------------------------------------
check_unchanged:
        jsr  ball_rect
        ldy  drawpg
        lda  a:dirty_cnt,y
        beq  L0CC1
        sta  rcnt
        tya
        beq  L0C9B
        lda  #$08
L0C9B:
        tay
L0C9C:
        lda  dl_y0,y
        cmp  rect+1
        beq  L0CA5
        bcs  L0CBC
L0CA5:
        lda  dl_y1,y
        cmp  rect
        bcc  L0CBC
        lda  dl_x0,y
        cmp  rect+3
        beq  L0CB5
        bcs  L0CBC
L0CB5:
        lda  dl_x1,y
        cmp  rect+2
        bcs  L0CC6
L0CBC:
        iny
        dec  rcnt
        bne  L0C9C
L0CC1:
        lda  #$01
        sta  nw_keep,x
L0CC6:
        rts

;---------------------------------------------------------------------------
; sprite_pos -- from ball X (8.8 position in $10-$13, angle in $36/$37)
; compute rotation frame (0-15), byte column, pre-shift and top row.
;---------------------------------------------------------------------------
sprite_pos:
        stx  tmp
        lda  bangle+1
        clc
        adc  #$08
        lsr a
        lsr a
        lsr a
        lsr a
        ldx  tmp
        sta  nw_frame,x
        lda  bx
        cmp  #$80
        lda  bx+1
        adc  #$00
        tay
        lda  x_col,y
        sta  nw_col,x
        lda  x_shift,y
        sta  nw_shift,x
        lda  by
        cmp  #$80
        lda  by+1
        adc  #$00
        sec
        sbc  #$06
        bcs  L0CFB
        lda  #$00
L0CFB:
        cmp  #$B4
        bcc  L0D01
        lda  #$B4
L0D01:
        sta  nw_row,x
        rts

;---------------------------------------------------------------------------
; erase_ball -- if slot Y holds a drawn sprite on this page, copy its
; 12x3 bytes back from the clean background at $A000.  The three LDA
; operands are patched with the row tables offset by the sprite row.
;---------------------------------------------------------------------------
erase_ball:
        lda  dr_valid,y
        bne  L0D0B
        rts
L0D0B:
        lda  #$00
        sta  dr_valid,y
        lda  dr_col,y
        sta  scol
        lda  dr_row,y
        clc
        adc  #<row_lo
        sta  ers_rowlo
        lda  #$00
        adc  #>row_lo
        sta  ers_rowlo+1
        lda  dr_row,y
        clc
        adc  #<row_hibg
        sta  ers_bufhi
        lda  #$00
        adc  #>row_hibg
        sta  ers_bufhi+1
        lda  dr_row,y
        clc
        adc  rowhi_tab
        sta  ers_rowhi
        lda  #$00
        adc  rowhi_tab+1
        sta  ers_rowhi+1
        ldx  #$00
erase_row:
ers_rowlo := * + 1
        lda  row_lo,x                   ; self-modified: row_lo + row
        sta  ptr
        sta  ptr2
ers_rowhi := * + 1
        lda  row_hi1,x                  ; self-modified: row_hi of page + row
        sta  ptr+1
ers_bufhi := * + 1
        lda  row_hibg,x                 ; self-modified: row_hibg + row
        sta  ptr2+1
        ldy  scol
        lda  (ptr2),y
        sta  (ptr),y
        iny
        lda  (ptr2),y
        sta  (ptr),y
        iny
        lda  (ptr2),y
        sta  (ptr),y
        inx
        cpx  #$0C
        bne  erase_row
        rts

;---------------------------------------------------------------------------
; draw_ball -- remember ball X's sprite in this page's slot, then OR its
; 12 rows x 3 bytes into the page.  The sprite comes from the pre-shifted,
; pre-rotated set in language-card RAM ($D000): the three ORA operands are
; patched to point at frame/column/shift.
;---------------------------------------------------------------------------
draw_ball:
        lda  nw_col,x
        sta  scol
        lda  nw_shift,x
        sta  sshift
        lda  nw_row,x
        sta  srow
        lda  nw_frame,x
        sta  tmp
        txa
        clc
        adc  pgslot
        tay
        lda  srow
        sta  dr_row,y
        lda  scol
        sta  dr_col,y
        lda  tmp
        sta  dr_frame,y
        lda  sshift
        sta  dr_shift,y
        lda  #$01
        sta  dr_valid,y
        lda  srow
        clc
        adc  #<row_lo
        sta  drw_rowlo
        lda  #$00
        adc  #>row_lo
        sta  drw_rowlo+1
        lda  srow
        clc
        adc  rowhi_tab
        sta  drw_rowhi
        lda  #$00
        adc  rowhi_tab+1
        sta  drw_rowhi+1
        ldx  tmp
        lda  spr_c0_lo,x
        clc
        adc  sshift
        sta  drw_spr0
        lda  spr_c0_hi,x
        adc  #$00
        sta  drw_spr0+1
        lda  spr_c1_lo,x
        clc
        adc  sshift
        sta  drw_spr1
        lda  spr_c1_hi,x
        adc  #$00
        sta  drw_spr1+1
        lda  spr_c2_lo,x
        clc
        adc  sshift
        sta  drw_spr2
        lda  spr_c2_hi,x
        adc  #$00
        sta  drw_spr2+1
        ldx  #$00
draw_row:
drw_rowlo := * + 1
        lda  row_lo,x                   ; self-modified: row_lo + row
        sta  ptr
drw_rowhi := * + 1
        lda  row_hi1,x                  ; self-modified: row_hi of page + row
        sta  ptr+1
        ldy  scol
        lda  (ptr),y
drw_spr0 := * + 1
        ora  sprites,x                  ; self-modified: sprite column 0
        sta  (ptr),y
        iny
        lda  (ptr),y
drw_spr1 := * + 1
        ora  sprites,x                  ; self-modified: sprite column 1
        sta  (ptr),y
        iny
        lda  (ptr),y
drw_spr2 := * + 1
        ora  sprites,x                  ; self-modified: sprite column 2
        sta  (ptr),y
        inx
        cpx  #$0C
        bne  draw_row
        rts

;---------------------------------------------------------------------------
; wait_and_flip -- wait for the start of a vertical blank, and for at
; least two blanks since the last flip (so 30 fps max on NTSC, 25 on PAL),
; then show the page just drawn and switch drawing to the other one.
; The number of blanks that elapsed (2-4, capped) becomes the next
; frame's physics step count: one step per field.
;
; wait_vbl is the frame clock.  It depends on the //e meaning of
; RDVBLBAR: bit 7 toggles every frame and is 0 during vertical blank;
; each 1->0 edge increments vblcount.  On a //c, $C019 bit 7 is the
; VBL *interrupt* flag, which only latches when VBL interrupts are enabled
; through the IOU (this program never does, and runs with SEI).  The bit
; never changes, vblcount stays 0, and this loop spins forever: the
; program freezes on its first frame.
;---------------------------------------------------------------------------
wait_and_flip:
        lda  vblcount
        cmp  #$02                       ; target = max(2, blanks so far + 1)
        bcs  L0E28
        lda  #$02
        bne  L0E2A
L0E28:
        adc  #$00
L0E2A:
        sta  vblwant
wait_vbl:
        lda  RDVBLBAR                   ; //e: bit 7 = 0 during vertical blank
        and  #$80
        cmp  vblprev
        beq  L0E3D
        sta  vblprev
        and  #$80                       ; count 1 -> 0 transitions
        bne  L0E3D
        inc  vblcount
L0E3D:
        lda  vblcount
        cmp  vblwant
        bcc  wait_vbl
        cmp  #$05
        bcc  L0E49                      ; cap the catch-up at 4 steps
        lda  #$04
L0E49:
        sta  steps
        lda  #$00
        sta  vblcount
        lda  drawpg
        bne  L0E58
        sta  LOWSCR                     ; show HGR1
        beq  L0E5B
L0E58:
        sta  HISCR                      ; show HGR2
L0E5B:
        lda  drawpg
        eor  #$01
        sta  drawpg

;---------------------------------------------------------------------------
; set_draw_page -- pgoff = $20 when drawing HGR2, $00 for HGR1.
;---------------------------------------------------------------------------
set_draw_page:
        lda  drawpg
        beq  L0E67
        lda  #$20
L0E67:
        sta  pgoff
        rts

;---------------------------------------------------------------------------
; read_keyboard --
;   up / down arrows   : softness slider -/+ (and wake all balls)
;   left / right arrows: wobble slider -/+
;   SPACE              : spawn a ball (key_spawn)
;   P                  : pause / resume
;---------------------------------------------------------------------------
read_keyboard:
        lda  KBD
        bpl  L0EC7
        sta  KBDSTRB                    ; clear strobe
        cmp  #$8B                       ; up arrow
        beq  L0E7A
        cmp  #$8A                       ; down arrow
        bne  L0E86
L0E7A:
        pha
        ldx  #$02
        lda  #$00
L0E7F:
        sta  ob_asleep,x
        dex
        bpl  L0E7F
        pla
L0E86:
        cmp  #$8B
        bne  L0E91
        lda  soft
        beq  L0EC7
        dec  soft
        rts
L0E91:
        cmp  #$8A
        bne  L0E9E
        lda  soft
        cmp  #$07
        bcs  L0EC7
        inc  soft
        rts
L0E9E:
        cmp  #$88                       ; left arrow
        bne  L0EA9
        lda  wobble
        beq  L0EC7
        dec  wobble
        rts
L0EA9:
        cmp  #$95                       ; right arrow
        bne  L0EB6
        lda  wobble
        cmp  #$07
        bcs  L0EC7
        inc  wobble
        rts
L0EB6:
        and  #$5F                       ; SPACE ($A0) -> 0
        bne  L0EBD
        jmp  key_spawn
L0EBD:
        cmp  #$50                       ; 'P' / 'p'
        bne  L0EC7
        lda  paused
        eor  #$01
        sta  paused
L0EC7:
        rts

;---------------------------------------------------------------------------
; init -- copy the sprite + reciprocal data ($A000-$B0FF) into
; language-card RAM bank 1 at $D000-$E0FF, copy the HGR background to
; page 2 and to the clean copy at $A000, switch to full-screen HGR page 1,
; clear the object arrays, set the sliders (softness 3, wobble 5), spawn
; the first ball and enter main_loop.
;---------------------------------------------------------------------------
init:
        sei
        cld
        ldx  #$FF
        txs
        lda  LCRAM1RW                   ; LC bank 1: read RAM, write RAM
        lda  LCRAM1RW
        lda  #$00
        sta  ptr2
        lda  #>$A000
        sta  ptr2+1
        lda  #$00
        sta  ptr
        lda  #>sprites
        sta  ptr+1
        ldx  #$11                       ; 17 pages $A000 -> $D000
        ldy  #$00
L0EE7:
        lda  (ptr2),y
        sta  (ptr),y
        iny
        bne  L0EE7
        inc  ptr2+1
        inc  ptr+1
        dex
        bne  L0EE7
        lda  #$40                       ; background -> HGR2
        jsr  copy_hgr1
        lda  #$A0                       ; background -> clean copy at $A000
        jsr  copy_hgr1
        sta  TXTCLR                     ; graphics
        sta  MIXCLR                     ; full screen
        sta  HIRES                      ; hi-res
        sta  LOWSCR                     ; page 1
        lda  #$00
        tax
L0F0E:
        sta  ob_xlo,x
        inx
        bne  L0F0E
        ldx  #$61
L0F16:
        sta  bx_hit+$04,x
        dex
        bpl  L0F16
        sta  paused
        sta  frames
        sta  frames+1
        sta  dirty_cnt
        sta  dirty_cnt+1
        sta  spawntmr
        sta  vblcount
        lda  #$02
        sta  steps
        lda  #$FF                       ; force the sliders to be drawn
        sta  shown_soft
        lda  #$03
        sta  soft
        lda  #$05
        sta  wobble
        lda  #<$AD3C                    ; random seed $AD3C
        sta  seed
        lda  #>$AD3C
        sta  seed+1
        ldx  #$00
        jsr  spawn_ball
        lda  #$01
        sta  nballs
        sta  drawpg
        jsr  set_draw_page
        lda  RDVBLBAR
        and  #$80
        sta  vblprev
        jmp  main_loop

;---------------------------------------------------------------------------
; copy_hgr1 -- copy $2000-$3FFF to page A*256 ($4000 or $A000).
;---------------------------------------------------------------------------
copy_hgr1:
        sta  ptr+1
        lda  #$20
        sta  ptr2+1
        lda  #$00
        sta  ptr
        sta  ptr2
        ldx  #$20
        tay
L0F69:
        lda  (ptr2),y
        sta  (ptr),y
        iny
        bne  L0F69
        inc  ptr2+1
        inc  ptr+1
        dex
        bne  L0F69
        rts

;---------------------------------------------------------------------------
; mul8x8 -- unsigned A*X -> prod (16 bit), by quarter squares:
;   A*X = sq(X+A) - sq(X-A),  sq(n) = floor(n^2/4)
; The table bases are patched with A so indexing by X gives X+A and X-A.
;---------------------------------------------------------------------------
mul8x8:
        sta  m8_sqp_lo
        sta  m8_sqp_hi
        eor  #$FF
        sta  m8_sqm_lo
        sta  m8_sqm_hi
        sec
m8_sqp_lo := * + 1
        lda  sqr_lo,x
m8_sqm_lo := * + 1
        sbc  sqrm_lo,x
        sta  prod
m8_sqp_hi := * + 1
        lda  sqr_hi,x
m8_sqm_hi := * + 1
        sbc  sqrm_hi,x
        sta  prod+1
        rts

;---------------------------------------------------------------------------
; mul8x16 -- unsigned A * marg (16 bit) -> prod24 ($4A-$4C), two
; quarter-square products added with the middle byte aligned.
;---------------------------------------------------------------------------
mul8x16:
        sta  m16a_sqp_lo
        sta  m16a_sqp_hi
        sta  m16b_sqp_lo
        sta  m16b_sqp_hi
        eor  #$FF
        sta  m16a_sqm_lo
        sta  m16a_sqm_hi
        sta  m16b_sqm_lo
        sta  m16b_sqm_hi
        ldx  marg
        sec
m16a_sqp_lo := * + 1
        lda  sqr_lo,x
m16a_sqm_lo := * + 1
        sbc  sqrm_lo,x
        sta  prod24
m16a_sqp_hi := * + 1
        lda  sqr_hi,x
m16a_sqm_hi := * + 1
        sbc  sqrm_hi,x
        sta  prod24m
        ldx  marg+1
        sec
m16b_sqp_lo := * + 1
        lda  sqr_lo,x
m16b_sqm_lo := * + 1
        sbc  sqrm_lo,x
        sta  mtmp
m16b_sqp_hi := * + 1
        lda  sqr_hi,x
m16b_sqm_hi := * + 1
        sbc  sqrm_hi,x
        sta  prod24h
        lda  mtmp
        clc
        adc  prod24m
        sta  prod24m
        bcc  L0FE3
        inc  prod24h
L0FE3:
        rts

;---------------------------------------------------------------------------
; abs_marg -- marg = |marg|.
;---------------------------------------------------------------------------
abs_marg:
        lda  marg+1
        bpl  L0FF5
        lda  #$00
        sec
        sbc  marg
        sta  marg
        lda  #$00
        sbc  marg+1
        sta  marg+1
L0FF5:
        rts

;---------------------------------------------------------------------------
; fix_sign -- negate mres if msign bit 7 is set.
;---------------------------------------------------------------------------
fix_sign:
        bit  msign
        bpl  L1007
        lda  #$00
        sec
        sbc  mres
        sta  mres
        lda  #$00
        sbc  mres+1
        sta  mres+1
L1007:
        rts

;---------------------------------------------------------------------------
; mul_dir -- mres = marg * A / 64, A a signed direction component
; ($40 = +1.0, $C0 = -1.0).  0, +1 and -1 are short-cut.
;---------------------------------------------------------------------------
mul_dir:
        cmp  #$00
        beq  L1022
        cmp  #$40
        beq  L1027
        cmp  #$C0
        bne  L1030
        lda  #$00
        sec
        sbc  marg
        sta  mres
        lda  #$00
        sbc  marg+1
        sta  mres+1
        rts
L1022:
        sta  mres
        sta  mres+1
        rts
L1027:
        lda  marg
        sta  mres
        lda  marg+1
        sta  mres+1
        rts
L1030:
        sta  mtmp
        eor  marg+1
        sta  msign
        lda  mtmp
        bpl  L103F
        eor  #$FF
        clc
        adc  #$01
L103F:
        asl a
        asl a
        ldy  marg+1
        bpl  L1054
        tay
        lda  #$00
        sec
        sbc  marg
        sta  marg
        lda  #$00
        sbc  marg+1
        sta  marg+1
        tya
L1054:
        jsr  mul8x16

;---------------------------------------------------------------------------
; apply_msign -- mres = +-(prod24 bits 8-23) according to msign.
;---------------------------------------------------------------------------
apply_msign:
        bit  msign
        bmi  L1064
        lda  prod24m
        sta  mres
        lda  prod24h
        sta  mres+1
        rts
L1064:
        lda  #$00
        sec
        sbc  prod24m
        sta  mres
        lda  #$00
        sbc  prod24h
        sta  mres+1
        rts

;---------------------------------------------------------------------------
; mul_frac -- mres = marg * A / 256 (marg signed, A unsigned fraction).
;---------------------------------------------------------------------------
mul_frac:
        ldy  marg
        bne  L107F
        ldy  marg+1
        bne  L107F
        sty  mres
        sty  mres+1
        rts
L107F:
        ldy  marg+1
        sty  msign
        bpl  L1094
        tay
        lda  #$00
        sec
        sbc  marg
        sta  marg
        lda  #$00
        sbc  marg+1
        sta  marg+1
        tya
L1094:
        jsr  mul8x16
        jmp  apply_msign

;---------------------------------------------------------------------------
; mul_k73 / mul_k183 / mul_k252 / mul_k230 -- mres = marg * k / 256
; for a fixed k, using quarter-square tables pre-offset by k (one table
; lookup pair per byte instead of patching).
;---------------------------------------------------------------------------
mul_k73:
        ldy  marg
        bne  L10A7
        ldy  marg+1
        bne  L10A7
        sty  mres
        sty  mres+1
        rts
L10A7:
        ldy  marg+1
        sty  msign
        bpl  L10BA
        lda  #$00
        sec
        sbc  marg
        sta  marg
        lda  #$00
        sbc  marg+1
        sta  marg+1
L10BA:
        ldx  marg
        sec
        lda  sqr_lo+$49,x
        sbc  sqrm_lo+$B6,x
        lda  sqr_hi+$49,x
        sbc  sqrm_hi+$B6,x
        sta  prod24m
        ldx  marg+1
        sec
        lda  sqr_lo+$49,x
        sbc  sqrm_lo+$B6,x
        tay
        lda  sqr_hi+$49,x
        sbc  sqrm_hi+$B6,x
        sta  prod24h
        tya
        clc
        adc  prod24m
        sta  prod24m
        bcc  L10E7
        inc  prod24h
L10E7:
        jmp  apply_msign
mul_k183:
        ldy  marg
        bne  L10F7
        ldy  marg+1
        bne  L10F7
        sty  mres
        sty  mres+1
        rts
L10F7:
        ldy  marg+1
        sty  msign
        bpl  L110A
        lda  #$00
        sec
        sbc  marg
        sta  marg
        lda  #$00
        sbc  marg+1
        sta  marg+1
L110A:
        ldx  marg
        sec
        lda  sqr_lo+$B7,x
        sbc  sqrm_lo+$48,x
        lda  sqr_hi+$B7,x
        sbc  sqrm_hi+$48,x
        sta  prod24m
        ldx  marg+1
        sec
        lda  sqr_lo+$B7,x
        sbc  sqrm_lo+$48,x
        tay
        lda  sqr_hi+$B7,x
        sbc  sqrm_hi+$48,x
        sta  prod24h
        tya
        clc
        adc  prod24m
        sta  prod24m
        bcc  L1137
        inc  prod24h
L1137:
        jmp  apply_msign
mul_k252:
        ldy  marg
        bne  L1147
        ldy  marg+1
        bne  L1147
        sty  mres
        sty  mres+1
        rts
L1147:
        ldy  marg+1
        sty  msign
        bpl  L115A
        lda  #$00
        sec
        sbc  marg
        sta  marg
        lda  #$00
        sbc  marg+1
        sta  marg+1
L115A:
        ldx  marg
        sec
        lda  sqr_lo+$FC,x
        sbc  sqrm_lo+$03,x
        lda  sqr_hi+$FC,x
        sbc  sqrm_hi+$03,x
        sta  prod24m
        ldx  marg+1
        sec
        lda  sqr_lo+$FC,x
        sbc  sqrm_lo+$03,x
        tay
        lda  sqr_hi+$FC,x
        sbc  sqrm_hi+$03,x
        sta  prod24h
        tya
        clc
        adc  prod24m
        sta  prod24m
        bcc  L1187
        inc  prod24h
L1187:
        jmp  apply_msign
mul_k230:
        ldy  marg
        bne  L1197
        ldy  marg+1
        bne  L1197
        sty  mres
        sty  mres+1
        rts
L1197:
        ldy  marg+1
        sty  msign
        bpl  L11AA
        lda  #$00
        sec
        sbc  marg
        sta  marg
        lda  #$00
        sbc  marg+1
        sta  marg+1
L11AA:
        ldx  marg
        sec
        lda  sqr_lo+$E6,x
        sbc  sqrm_lo+$19,x
        lda  sqr_hi+$E6,x
        sbc  sqrm_hi+$19,x
        sta  prod24m
        ldx  marg+1
        sec
        lda  sqr_lo+$E6,x
        sbc  sqrm_lo+$19,x
        tay
        lda  sqr_hi+$E6,x
        sbc  sqrm_hi+$19,x
        sta  prod24h
        tya
        clc
        adc  prod24m
        sta  prod24m
        bcc  L11D7
        inc  prod24h
L11D7:
        jmp  apply_msign

;---------------------------------------------------------------------------
; mul_int -- mres = marg * A (signed 16 x unsigned 8, low 16 bits kept).
;---------------------------------------------------------------------------
mul_int:
        ldy  marg
        bne  L11E7
        ldy  marg+1
        bne  L11E7
        sty  mres
        sty  mres+1
        rts
L11E7:
        pha
        lda  marg+1
        sta  msign
        jsr  abs_marg
        pla
        jsr  mul8x16
        lda  prod24
        sta  mres
        lda  prod24m
        sta  mres+1
        jmp  fix_sign

;---------------------------------------------------------------------------
; isqrt16 -- root = floor(sqrt(num)): start from sqrt_seed[num hi] and
; step up while (root+1)^2 <= num.
;---------------------------------------------------------------------------
isqrt16:
        ldx  numhi
        lda  sqrt_seed,x
        sta  root
L1205:
        ldx  root
        inx
        txa
        jsr  mul8x8
        lda  num
        cmp  prod
        lda  numhi
        sbc  prod+1
        bcc  L121A
        inc  root
        bne  L1205
L121A:
        rts

;---------------------------------------------------------------------------
; div16by8 -- num = num / A (8-bit quotient), via the 65536/A reciprocal
; table in LC RAM, then a one-step correction.
;---------------------------------------------------------------------------
div16by8:
        sta  divisor
        tax
        lda  recip_lo,x
        sta  marg
        lda  recip_hi,x
        sta  marg+1
        lda  numhi
        asl a
        asl a
        sta  root
        lda  num
        rol a
        rol a
        rol a
        and  #$03
        ora  root
        jsr  mul8x16
        lda  prod24m
        lsr  prod24h
        ror a
        lsr  prod24h
        ror a
        sta  root
        tax
        inx
        txa
        ldx  divisor
        jsr  mul8x8
        lda  num
        cmp  prod
        lda  numhi
        sbc  prod+1
        bcc  L1258
        inc  root
L1258:
        lda  root
        sta  num
        lda  #$00
        sta  numhi
        rts

;---------------------------------------------------------------------------
; integrate_ball -- vy += $18 (gravity, 0.094 px/step^2); clamp vx and
; vy to +-4 px/step; x += vx; y += vy; angle += angle rate.
;---------------------------------------------------------------------------
integrate_ball:
        lda  ob_vylo,x                  ; gravity
        clc
        adc  #$18
        sta  ob_vylo,x
        lda  ob_vyhi,x
        adc  #$00
        sta  ob_vyhi,x
        lda  ob_vxhi,x
        bmi  L128F
        lda  ob_vxlo,x
        cmp  #$00
        lda  ob_vxhi,x
        sbc  #$04
        bcc  L12A6                      ; vx > 4 -> 4
        lda  #$00
        sta  ob_vxlo,x
        lda  #$04
        sta  ob_vxhi,x
        bne  L12A6
L128F:
        lda  ob_vxlo,x
        clc
        adc  #$00
        lda  ob_vxhi,x
        adc  #$04
        bpl  L12A6                      ; vx < -4 -> -4
        lda  #$00
        sta  ob_vxlo,x
        lda  #$FC
        sta  ob_vxhi,x
L12A6:
        lda  ob_vyhi,x
        bmi  L12C3
        lda  ob_vylo,x
        cmp  #$00
        lda  ob_vyhi,x
        sbc  #$04
        bcc  L12DA
        lda  #$00
        sta  ob_vylo,x
        lda  #$04
        sta  ob_vyhi,x
        bne  L12DA
L12C3:
        lda  ob_vylo,x
        clc
        adc  #$00
        lda  ob_vyhi,x
        adc  #$04
        bpl  L12DA
        lda  #$00
        sta  ob_vylo,x
        lda  #$FC
        sta  ob_vyhi,x
L12DA:
        lda  ob_xlo,x
        clc
        adc  ob_vxlo,x
        sta  ob_xlo,x
        lda  ob_xhi,x
        adc  ob_vxhi,x
        sta  ob_xhi,x
        lda  ob_ylo,x
        clc
        adc  ob_vylo,x
        sta  ob_ylo,x
        lda  ob_yhi,x
        adc  ob_vyhi,x
        sta  ob_yhi,x
        lda  ob_anglo,x
        clc
        adc  ob_ratelo,x
        sta  ob_anglo,x
        lda  ob_anghi,x
        adc  ob_ratehi,x
        sta  ob_anghi,x
        rts

;---------------------------------------------------------------------------
; collide_boxes -- look up the ball's 16x16-pixel grid cell, walk that
; cell's $FF-terminated list of boxes (0-3 are the screen walls, 4-10
; the boxes) and collide_box with each.  If any contact touched the
; ball's spin, recompute its angle rate.
;---------------------------------------------------------------------------
collide_boxes:
        lda  #$00
        sta  hitflag
        lda  by+1                       ; grid cell = (y & $F0) | x>>4
        and  #$F0
        sta  tmp
        lda  bx+1
        lsr a
        lsr a
        lsr a
        lsr a
        ora  tmp
        tax
        lda  grid_cell,x
        sta  gridptr
L132C:
        ldy  gridptr
        lda  grid_lists,y
        bmi  L134F
        sta  boxi
        tax
        lda  RDVBLBAR
        and  #$80
        cmp  vblprev
        beq  L1347
        sta  vblprev
        and  #$80
        bne  L1347
        inc  vblcount
L1347:
        jsr  collide_box
        inc  gridptr
        jmp  L132C
L134F:
        lda  hitflag
        beq  L1356
        jmp  spin_to_rate
L1356:
        rts

;---------------------------------------------------------------------------
; collide_box -- closest point of box X to the ball, distance by
; quarter squares; contact when closer than 6 px (the ball radius).
; Computes the unit normal (nx, ny) then goes to `contact`.
;---------------------------------------------------------------------------
collide_box:
        lda  bx+1
        cmp  box_left,x
        bcs  L1376
        lda  #$00
        sta  cptx
        sec
        sbc  bx
        sta  dx
        lda  box_left,x
        sta  cptx+1
        sbc  bx+1
        sta  dx+1
        lda  #$FF
        sta  sgnx
        bne  L13A6
L1376:
        cmp  box_right,x
        bcc  L1396
        lda  #$00
        sta  cptx
        lda  bx
        sta  dx
        lda  box_right,x
        sta  cptx+1
        lda  bx+1
        sec
        sbc  box_right,x
        sta  dx+1
        lda  #$01
        sta  sgnx
        bne  L13A6
L1396:
        lda  bx
        sta  cptx
        lda  bx+1
        sta  cptx+1
        lda  #$00
        sta  dx
        sta  dx+1
        sta  sgnx
L13A6:
        lda  dx+1
        cmp  #$06
        bcc  L13AF
        jmp  no_contact
L13AF:
        lda  by+1
        cmp  box_top,x
        bcs  L13CE
        lda  #$00
        sta  cpty
        sec
        sbc  by
        sta  dy
        lda  box_top,x
        sta  cpty+1
        sbc  by+1
        sta  dy+1
        lda  #$FF
        sta  sgny
        bne  L13FE
L13CE:
        cmp  box_bottom,x
        bcc  L13EE
        lda  #$00
        sta  cpty
        lda  by
        sta  dy
        lda  box_bottom,x
        sta  cpty+1
        lda  by+1
        sec
        sbc  box_bottom,x
        sta  dy+1
        lda  #$01
        sta  sgny
        bne  L13FE
L13EE:
        lda  by
        sta  cpty
        lda  by+1
        sta  cpty+1
        lda  #$00
        sta  dy
        sta  dy+1
        sta  sgny
L13FE:
        lda  dy+1
        cmp  #$06
        bcc  L1407
        jmp  no_contact
L1407:
        lda  dx+1
        asl a
        asl a
        asl a
        asl a
        sta  dxs
        lda  dx
        lsr a
        lsr a
        lsr a
        lsr a
        ora  dxs
        sta  dxs
        lda  dy+1
        asl a
        asl a
        asl a
        asl a
        sta  dys
        lda  dy
        lsr a
        lsr a
        lsr a
        lsr a
        ora  dys
        sta  dys
        lda  dxs
        tax
        jsr  mul8x8
        lda  prod
        sta  num
        lda  prod+1
        sta  numhi
        lda  dys
        tax
        jsr  mul8x8
        lda  num
        clc
        adc  prod
        sta  num
        lda  numhi
        adc  prod+1
        sta  numhi
        bcs  no_contact
        lda  num
        cmp  #$00
        lda  numhi
        sbc  #$24                       ; dist^2 < 36 px^2 ?
        bcc  L1459
no_contact:
        rts
L1459:
        lda  dxs
        bne  L1477
        lda  dys
        bne  L1464
        jmp  L14ED
L1464:
        sta  dist
        lda  #$00
        sta  nx
        lda  #$40
        ldy  sgny
        bpl  L1472
        lda  #$C0
L1472:
        sta  ny
        jmp  contact
L1477:
        lda  dys
        bne  L148E
        sta  ny
        lda  dxs
        sta  dist
        lda  #$40
        ldy  sgnx
        bpl  L1489
        lda  #$C0
L1489:
        sta  nx
        jmp  contact
L148E:
        jsr  isqrt16
        lda  root
        sta  dist
        lda  RDVBLBAR
        and  #$80
        cmp  vblprev
        beq  L14A6
        sta  vblprev
        and  #$80
        bne  L14A6
        inc  vblcount
L14A6:
        lda  dxs
        lsr a
        lsr a
        sta  numhi
        lda  dxs
        asl a
        asl a
        asl a
        asl a
        asl a
        asl a
        sta  num
        lda  dist
        jsr  div16by8
        lda  num
        ldy  sgnx
        bpl  L14C6
        eor  #$FF
        clc
        adc  #$01
L14C6:
        sta  nx
        lda  dys
        lsr a
        lsr a
        sta  numhi
        lda  dys
        asl a
        asl a
        asl a
        asl a
        asl a
        asl a
        sta  num
        lda  dist
        jsr  div16by8
        lda  num
        ldy  sgny
        bpl  L14E8
        eor  #$FF
        clc
        adc  #$01
L14E8:
        sta  ny
        jmp  contact
L14ED:
        lda  #$00
        sta  nx
        sta  cpty
        lda  #$C0
        sta  ny
        ldx  boxi
        lda  box_top,x
        sta  cpty+1
        lda  bx
        sta  cptx
        lda  bx+1
        sta  cptx+1

;---------------------------------------------------------------------------
; hard_contact -- push the ball out to exactly 6 px from the contact
; point; if moving into the box, reflect the normal velocity (x 0.5625,
; or stop it below ~0.18 px/step) and apply surface friction/spin.
;---------------------------------------------------------------------------
hard_contact:
        lda  nx
        bmi  L151F
        ldx  #$18
        jsr  mul8x8
        lda  cptx
        clc
        adc  prod
        sta  bx
        lda  cptx+1
        adc  prod+1
        sta  bx+1
        jmp  L1536
L151F:
        eor  #$FF
        clc
        adc  #$01
        ldx  #$18
        jsr  mul8x8
        lda  cptx
        sec
        sbc  prod
        sta  bx
        lda  cptx+1
        sbc  prod+1
        sta  bx+1
L1536:
        lda  ny
        bmi  L154F
        ldx  #$18
        jsr  mul8x8
        lda  cpty
        clc
        adc  prod
        sta  by
        lda  cpty+1
        adc  prod+1
        sta  by+1
        jmp  L1566
L154F:
        eor  #$FF
        clc
        adc  #$01
        ldx  #$18
        jsr  mul8x8
        lda  cpty
        sec
        sbc  prod
        sta  by
        lda  cpty+1
        sbc  prod+1
        sta  by+1
L1566:
        jsr  normal_speed
        bmi  L156C
        rts
L156C:
        jsr  friction
        lda  vn
        clc
        adc  #$2F
        lda  vn+1
        adc  #$00
        bpl  L1597
        lda  #$00
        sec
        sbc  vn
        sta  marg
        lda  #$00
        sbc  vn+1
        sta  marg+1
        lda  #$90                       ; restitution 144/256
        jsr  mul_frac
        lda  mres
        sta  vn
        lda  mres+1
        sta  vn+1
        jmp  rebuild_velocity
L1597:
        lda  #$00
        sta  vn
        sta  vn+1
        jmp  rebuild_velocity

;---------------------------------------------------------------------------
; contact -- boxes 4-10 behave as soft springs when the softness
; slider is above 0 (soft_contact); walls and rigid boxes use hard_contact.
;---------------------------------------------------------------------------
contact:
        ldx  boxi
        cpx  #$04
        bcc  L15B0
        ldx  soft                       ; box 4-10: soft if slider > 0
        lda  soft_tab,x
        beq  L15B0
        jmp  soft_contact
L15B0:
        jmp  hard_contact

;---------------------------------------------------------------------------
; normal_speed -- vn = v . n  (returns N = sign).
;---------------------------------------------------------------------------
normal_speed:
        lda  bvx
        sta  marg
        lda  bvx+1
        sta  marg+1
        lda  nx
        jsr  mul_dir
        lda  mres
        sta  vn
        lda  mres+1
        sta  vn+1
        lda  bvy
        sta  marg
        lda  bvy+1
        sta  marg+1
        lda  ny
        jsr  mul_dir
        lda  vn
        clc
        adc  mres
        sta  vn
        lda  vn+1
        adc  mres+1
        sta  vn+1
        lda  vn+1
        rts

;---------------------------------------------------------------------------
; friction -- tangential speed vt = v . t (t = n rotated), slip =
; vt - spin; vt -= slip*73/256, spin += slip*183/256, then both
; x 252/256.  Rolling friction that couples spin and travel.
;---------------------------------------------------------------------------
friction:
        lda  RDVBLBAR
        and  #$80
        cmp  vblprev
        beq  L15F6
        sta  vblprev
        and  #$80
        bne  L15F6
        inc  vblcount
L15F6:
        lda  bvx
        sta  marg
        lda  bvx+1
        sta  marg+1
        lda  #$00
        sec
        sbc  ny
        jsr  mul_dir
        lda  mres
        sta  vt
        lda  mres+1
        sta  vt+1
        lda  bvy
        sta  marg
        lda  bvy+1
        sta  marg+1
        lda  nx
        jsr  mul_dir
        lda  vt
        clc
        adc  mres
        sta  vt
        lda  vt+1
        adc  mres+1
        sta  vt+1
        lda  vt
        sec
        sbc  bspin
        sta  slip
        lda  vt+1
        sbc  bspin+1
        sta  slip+1
        lda  slip
        sta  marg
        lda  slip+1
        sta  marg+1
        jsr  mul_k73
        lda  vt
        sec
        sbc  mres
        sta  vt
        lda  vt+1
        sbc  mres+1
        sta  vt+1
        lda  slip
        sta  marg
        lda  slip+1
        sta  marg+1
        jsr  mul_k183
        lda  bspin
        clc
        adc  mres
        sta  bspin
        lda  bspin+1
        adc  mres+1
        sta  bspin+1
        lda  vt
        sta  marg
        lda  vt+1
        sta  marg+1
        jsr  mul_k252
        lda  mres
        sta  vt
        lda  mres+1
        sta  vt+1
        lda  bspin
        sta  marg
        lda  bspin+1
        sta  marg+1
        jsr  mul_k252
        lda  mres
        sta  bspin
        lda  mres+1
        sta  bspin+1
        rts

;---------------------------------------------------------------------------
; rebuild_velocity -- v = vn*n + vt*t; flag the spin change (hitflag).
;---------------------------------------------------------------------------
rebuild_velocity:
        lda  RDVBLBAR
        and  #$80
        cmp  vblprev
        beq  L169D
        sta  vblprev
        and  #$80
        bne  L169D
        inc  vblcount
L169D:
        lda  vt
        sta  marg
        lda  vt+1
        sta  marg+1
        lda  #$00
        sec
        sbc  ny
        jsr  mul_dir
        lda  mres
        sta  bvx
        lda  mres+1
        sta  bvx+1
        lda  vn
        sta  marg
        lda  vn+1
        sta  marg+1
        lda  nx
        jsr  mul_dir
        lda  bvx
        clc
        adc  mres
        sta  bvx
        lda  bvx+1
        adc  mres+1
        sta  bvx+1
        lda  vt
        sta  marg
        lda  vt+1
        sta  marg+1
        lda  nx
        jsr  mul_dir
        lda  mres
        sta  bvy
        lda  mres+1
        sta  bvy+1
        lda  vn
        sta  marg
        lda  vn+1
        sta  marg+1
        lda  ny
        jsr  mul_dir
        lda  bvy
        clc
        adc  mres
        sta  bvy
        lda  bvy+1
        adc  mres+1
        sta  bvy+1
        lda  #$01
        sta  hitflag
        rts

;---------------------------------------------------------------------------
; soft_contact -- spring contact with a box: penetration p = 6 px - dist.
; Deeper than 4 px: put the ball centre 2 px from the surface, use p = 4
; and (deepflag) cancel any outward normal speed.  Then
; vn = vn*230/256 + p*soft_tab[soft]/256 (a spring pushing out, with
; loss), friction as usual, rebuild_velocity, and record_hit stores
; which side was hit, where and how deep (0-4 px) so the box can be
; drawn dented.
;---------------------------------------------------------------------------
soft_contact:
        lda  #$00
        sta  deepflag
        lda  #$60
        sec
        sbc  dist
        cmp  #$41
        bcc  L1774
        inc  deepflag
        lda  nx
        bmi  L172B
        ldx  #$08
        jsr  mul8x8
        lda  cptx
        clc
        adc  prod
        sta  bx
        lda  cptx+1
        adc  prod+1
        sta  bx+1
        jmp  L1742
L172B:
        eor  #$FF
        clc
        adc  #$01
        ldx  #$08
        jsr  mul8x8
        lda  cptx
        sec
        sbc  prod
        sta  bx
        lda  cptx+1
        sbc  prod+1
        sta  bx+1
L1742:
        lda  ny
        bmi  L175B
        ldx  #$08
        jsr  mul8x8
        lda  cpty
        clc
        adc  prod
        sta  by
        lda  cpty+1
        adc  prod+1
        sta  by+1
        jmp  L1772
L175B:
        eor  #$FF
        clc
        adc  #$01
        ldx  #$08
        jsr  mul8x8
        lda  cpty
        sec
        sbc  prod
        sta  by
        lda  cpty+1
        sbc  prod+1
        sta  by+1
L1772:
        lda  #$40
L1774:
        sta  force
        lda  #$00
        sta  force+1
        asl  force
        rol  force+1
        asl  force
        rol  force+1
        asl  force
        rol  force+1
        asl  force
        rol  force+1
        jsr  normal_speed
        jsr  friction
        lda  deepflag
        beq  L179E
        lda  vn+1
        bpl  L179E
        lda  #$00
        sta  vn
        sta  vn+1
L179E:
        lda  vn
        sta  marg
        lda  vn+1
        sta  marg+1
        jsr  mul_k230
        lda  mres
        sta  vn
        lda  mres+1
        sta  vn+1
        lda  force
        sta  marg
        lda  force+1
        sta  marg+1
        ldx  soft
        lda  soft_tab,x
        jsr  mul_frac
        lda  vn
        clc
        adc  mres
        sta  vn
        lda  vn+1
        adc  mres+1
        sta  vn+1
        jsr  rebuild_velocity
record_hit:
        ldx  boxi
        lda  nx
        bpl  L17DC
        eor  #$FF
        clc
        adc  #$01
L17DC:
        sta  tmp
        lda  ny
        bpl  L17E7
        eor  #$FF
        clc
        adc  #$01
L17E7:
        cmp  tmp
        bcc  L1825
        jsr  round_x
        cmp  box_left,x
        bcs  L17F6
        lda  box_left,x
L17F6:
        cmp  box_right,x
        bcc  L1800
        lda  box_right,x
        sbc  #$01
L1800:
        sta  hitpos
        jsr  round_y
        ldy  ny
        bpl  L1815
        clc
        adc  #$06
        sec
        sbc  box_top,x
        ldy  #$00
        jmp  L185C
L1815:
        sta  tmp
        lda  box_bottom,x
        sec
        sbc  tmp
        clc
        adc  #$06
        ldy  #$01
        jmp  L185C
L1825:
        jsr  round_y
        cmp  box_top,x
        bcs  L1830
        lda  box_top,x
L1830:
        cmp  box_bottom,x
        bcc  L183A
        lda  box_bottom,x
        sbc  #$01
L183A:
        sta  hitpos
        jsr  round_x
        ldy  nx
        bpl  L184F
        clc
        adc  #$06
        sec
        sbc  box_left,x
        ldy  #$02
        jmp  L185C
L184F:
        sta  tmp
        lda  box_right,x
        sec
        sbc  tmp
        clc
        adc  #$06
        ldy  #$03
L185C:
        sty  side
        tax
        bpl  L1863
        lda  #$00
L1863:
        cmp  #$05
        bcc  L1869
        lda  #$04
L1869:
        sta  hitdepth
        ldx  boxi
        lda  #$01
        sta  bx_hit,x
        lda  side
        sta  bx_hitside,x
        lda  hitpos
        sta  bx_hitpos,x
        lda  hitdepth
        sta  bx_hitdepth,x
        txa
        ldx  curball
        sta  ob_hitbox,x
        lda  side
        sta  ob_hitside,x
        lda  hitpos
        sta  ob_hitpos,x
        lda  hitdepth
        sta  ob_hitdepth,x
        rts

;---------------------------------------------------------------------------
; round_x / round_y -- A = ball x (or y) rounded to a whole pixel.
;---------------------------------------------------------------------------
round_x:
        lda  bx
        cmp  #$80
        lda  bx+1
        adc  #$00
        rts
round_y:
        lda  by
        cmp  #$80
        lda  by+1
        adc  #$00
        rts

;---------------------------------------------------------------------------
; box_spring -- box X (4-10).  When hit this step, its dent jumps to the
; recorded depth (and its spring velocity keeps the difference).  Else,
; while active: vel = vel*damp_tab[wobble]/256 - disp*stiff_tab[soft]/256,
; disp += vel; when both are within +-1/8 the box comes to rest.
;---------------------------------------------------------------------------
box_spring:
        lda  bx_hit,x
        beq  L18EC
        lda  bx_active,x
        bne  L18BD
        lda  #$00
        sta  bx_vello,x
        sta  bx_velhi,x
        beq  L18CF
L18BD:
        lda  #$00
        sec
        sbc  bx_displo,x
        sta  bx_vello,x
        lda  bx_hitdepth,x
        sbc  bx_disphi,x
        sta  bx_velhi,x
L18CF:
        lda  #$00
        sta  bx_displo,x
        lda  bx_hitdepth,x
        sta  bx_disphi,x
        lda  #$01
        sta  bx_active,x
        lda  bx_hitside,x
        sta  bx_side,x
        lda  bx_hitpos,x
        sta  bx_pos,x
        rts
L18EC:
        lda  bx_active,x
        bne  L18F2
        rts
L18F2:
        lda  RDVBLBAR
        and  #$80
        cmp  vblprev
        beq  L1903
        sta  vblprev
        and  #$80
        bne  L1903
        inc  vblcount
L1903:
        ldx  boxloop
        lda  bx_displo,x
        sta  sdisp
        lda  bx_disphi,x
        sta  sdisp+1
        lda  bx_vello,x
        sta  svel
        lda  bx_velhi,x
        sta  svel+1
        lda  svel
        sta  marg
        lda  svel+1
        sta  marg+1
        ldx  wobble
        lda  damp_tab,x
        jsr  mul_frac
        lda  mres
        sta  svel
        lda  mres+1
        sta  svel+1
        lda  sdisp
        sta  marg
        lda  sdisp+1
        sta  marg+1
        ldx  soft
        lda  stiff_tab,x
        jsr  mul_frac
        lda  svel
        sec
        sbc  mres
        sta  svel
        lda  svel+1
        sbc  mres+1
        sta  svel+1
        lda  sdisp
        clc
        adc  svel
        sta  sdisp
        lda  sdisp+1
        adc  svel+1
        sta  sdisp+1
        ldx  boxloop
        lda  sdisp
        sta  bx_displo,x
        lda  sdisp+1
        sta  bx_disphi,x
        lda  svel
        sta  bx_vello,x
        lda  svel+1
        sta  bx_velhi,x
        ldx  #$59
        jsr  is_small
        bcs  L1992
        ldx  #$5B
        jsr  is_small
        bcs  L1992
        ldx  boxloop
        lda  #$00
        sta  bx_active,x
        sta  bx_displo,x
        sta  bx_disphi,x
        sta  bx_vello,x
        sta  bx_velhi,x
L1992:
        rts

;---------------------------------------------------------------------------
; is_small -- same test as is_slow.
;---------------------------------------------------------------------------
is_small:
        lda  $00,x
        clc
        adc  #$20
        tay
        lda  $01,x
        adc  #$00
        bne  L19A2
        cpy  #$40
        rts
L19A2:
        sec
        rts

;---------------------------------------------------------------------------
; collide_pair -- balls ball_a / ball_b closer than 12 px: wake both,
; push each apart along the normal by half the overlap, and if they
; approach apply an impulse J = -vn*k along the normal (equal masses):
; k = 200/256 when fast (restitution about 0.56), 128/256 when slower
; than ~0.18 px/step (fully inelastic).  No spin transfer.
;---------------------------------------------------------------------------
collide_pair:
        lda  RDVBLBAR
        and  #$80
        cmp  vblprev
        beq  L19B5
        sta  vblprev
        and  #$80
        bne  L19B5
        inc  vblcount
L19B5:
        ldx  ball_a
        ldy  ball_b
        lda  ob_xlo,y
        sec
        sbc  ob_xlo,x
        sta  dx
        lda  ob_xhi,y
        sbc  ob_xhi,x
        sta  dx+1
        bpl  L19DD
        lda  #$00
        sec
        sbc  dx
        sta  dx
        lda  #$00
        sbc  dx+1
        sta  dx+1
        ldx  #$FF
        bne  L19DF
L19DD:
        ldx  #$01
L19DF:
        stx  sgnx
        lda  dx+1
        cmp  #$0C
        bcc  L19EA
        jmp  L1A70
L19EA:
        ldx  ball_a
        ldy  ball_b
        lda  ob_ylo,y
        sec
        sbc  ob_ylo,x
        sta  dy
        lda  ob_yhi,y
        sbc  ob_yhi,x
        sta  dy+1
        bpl  L1A12
        lda  #$00
        sec
        sbc  dy
        sta  dy
        lda  #$00
        sbc  dy+1
        sta  dy+1
        ldx  #$FF
        bne  L1A14
L1A12:
        ldx  #$01
L1A14:
